import subprocess
import time
import os
import re

def get_ngram(n_type, top_val):
    session = f"s_{os.getpid()}"
    subprocess.run(f"tmux new-session -d -s {session} './executable -n {n_type} -t {top_val} -c 1 -r 1'", shell=True)
    time.sleep(0.3)
    res = subprocess.run(f"tmux capture-pane -t {session} -p", shell=True, capture_output=True, text=True)
    subprocess.run(f"tmux kill-session -t {session}", shell=True)
    lines = res.stdout.splitlines()
    for i, line in enumerate(lines):
        if "Lesson #1" in line:
            if i + 3 < len(lines):
                # Remove │ and spaces
                ngram = line.strip().replace('│', '').strip()
                # Wait, the i+3 line was actually the ngram line.
                ngram = lines[i+3].replace('│', '').strip()
                return ngram
    return None

def collect(n_type, target):
    ngrams = []
    # Try -t 1, -t 2 ... up to target
    for i in range(1, target + 1):
        found = set()
        for _ in range(5):
            c = get_ngram(n_type, i)
            if c: found.add(c)
        new = found - set(ngrams)
        if new:
            ngrams.append(list(new)[0])
        else:
            ngrams.append("UNKNOWN")
        if i % 10 == 0: print(f"{n_type} {i}/{target}")
    return ngrams

for n in ['2', '3', '4', 'w']:
    ngrams = collect(n, 200)
    with open(f"ngrams_{n}.txt", 'w') as f:
        f.write(','.join(ngrams))
