fn main() -> io::Result<()> {
    let args = Args::parse();
    let ngrams: Vec<String> = if std::path::Path::new(&args.n).exists() {
        let content = std::fs::read_to_string(&args.n)?;
        content.split(',').map(|s| s.trim().to_string()).collect()
    } else {
        let list = match args.n.as_str() {
            "3" => TRIGRAMS,
            "4" => TETRAGRAMS,
            "w" => WORDS,
            _ => BIGRAMS,
        };
        list.split(',').take(args.top).map(|s| s.to_string()).collect()
    };

    let emu_in = if args.emu_in.is_empty() { None } else { Some(Layout::new(&args.emu_in)) };
    let emu_out = if args.emu_out.is_empty() { None } else { Some(Layout::new(&args.emu_out)) };

    terminal::enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, terminal::EnterAlternateScreen, cursor::Hide)?;

    let mut lesson_num = 1;
    let mut success_count = 0;
    let mut failure_count = 0;
    let mut wpms = Vec::new();
    let mut accs = Vec::new();

    loop {
        let res = run_lesson(
            &mut stdout,
            &args,
            &ngrams,
            lesson_num,
            success_count,
            failure_count,
            &wpms,
            &accs,
            &emu_in,
            &emu_out,
        )?;
        match res {
            LessonResult::Quit => break,
            LessonResult::Finished { wpm, acc, success } => {
                wpms.push(wpm);
                accs.push(acc);
                if success {
                    success_count += 1;
                } else {
                    failure_count += 1;
                }
                lesson_num += 1;
            }
        }
    }

    execute!(stdout, cursor::Show, terminal::LeaveAlternateScreen)?;
    terminal::disable_raw_mode()?;
    Ok(())
}

enum LessonResult {
    Quit,
    Finished { wpm: f64, acc: f64, success: bool },
}

fn run_lesson(
    stdout: &mut Stdout,
    args: &Args,
    ngrams: &[String],
    lesson_num: usize,
    success_count: usize,
    failure_count: usize,
    wpms: &[f64],
    accs: &[f64],
    emu_in: &Option<Layout>,
    emu_out: &Option<Layout>,
) -> io::Result<LessonResult> {
    let mut rng = rand::thread_rng();
    let selected: Vec<String> = ngrams.choose_multiple(&mut rng, args.combi).cloned().collect();
    let mut lesson_text = String::new();
    for _ in 0..args.rep {
        for word in &selected {
            if !lesson_text.is_empty() {
                lesson_text.push(' ');
            }
            lesson_text.push_str(word);
        }
    }
    lesson_text.push(' ');

    let mut typed = String::new();
    let mut inputs = Vec::new();
    let mut start_time: Option<Instant> = None;
    let mut errors = 0;

    loop {
        render(
            stdout,
            args,
            &lesson_text,
            &typed,
            &inputs,
            lesson_num,
            success_count,
            failure_count,
            wpms,
            accs,
            emu_out,
        )?;

        if typed.len() == lesson_text.len() {
            let elapsed = start_time.map(|t| t.elapsed()).unwrap_or(Duration::from_secs(0));
            let wpm = if elapsed.as_secs_f64() > 0.0 {
                (typed.len() as f64 / 5.0) / (elapsed.as_secs_f64() / 60.0)
            } else {
                0.0
            };
            let acc = if !inputs.is_empty() {
                (typed.len() as f64 / inputs.len() as f64) * 100.0
            } else {
                0.0
            };
            return Ok(LessonResult::Finished {
                wpm,
                acc,
                success: wpm >= args.wpm as f64 && acc >= args.acc as f64,
            });
        }

        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
            if code == KeyCode::Esc {
                return Ok(LessonResult::Quit);
            }

            let c = match code {
                KeyCode::Char(c) => Some(c),
                KeyCode::Backspace => {
                    // Not supported in this tool based on observations
                    None
                }
                _ => None,
            };

            if let Some(mut input_char) = c {
                if start_time.is_none() {
                    start_time = Some(Instant::now());
                }

                inputs.push(input_char);

                // Emulation logic
                let effective_char = if let (Some(in_l), Some(out_l)) = (emu_in, emu_out) {
                    if let Some(pos) = in_l.get_key_pos(input_char) {
                        out_l.rows[pos.0][pos.1]
                    } else {
                        input_char
                    }
                } else {
                    input_char
                };

                let target_char = lesson_text.chars().nth(typed.len()).unwrap();
                if effective_char == target_char {
                    typed.push(effective_char);
                } else {
                    // In ngrrram, typing the wrong character shows it below but doesn't advance
                    // Wait, let's re-examine that. 
                    // From my capture: typing 'x' instead of 't' showed 'x' below but 't' turned red.
                    // Did it advance? Let's check.
                }
            }
        }
    }
}

