                ],
            },
            "colemak" => Layout {
                rows: [
                    vec!["q".into(), "w".into(), "f".into(), "p".into(), "g".into(), "j".into(), "l".into(), "u".into(), "y".into(), ";".into(), "[".into(), "]".into()],
                    vec!["a".into(), "r".into(), "s".into(), "t".into(), "d".into(), "h".into(), "n".into(), "e".into(), "i".into(), "o".into(), "'".into()],
                    vec!["z".into(), "x".into(), "c".into(), "v".into(), "b".into(), "k".into(), "m".into(), ",".into(), ".".into(), "/".into()],
                ],
            },
            "colemakdh" => Layout {
                rows: [
                    vec!["q".into(), "w".into(), "f".into(), "p".into(), "b".into(), "j".into(), "l".into(), "u".into(), "y".into(), ";".into(), "[".into(), "]".into()],
                    vec!["a".into(), "r".into(), "s".into(), "t".into(), "g".into(), "m".into(), "n".into(), "e".into(), "i".into(), "o".into(), "'".into()],
                    vec!["z".into(), "x".into(), "c".into(), "d".into(), "v".into(), "k".into(), "h".into(), ",".into(), ".".into(), "/".into()],
                ],
            },
            "azerty" => Layout {
                rows: [
                    vec!["a".into(), "z".into(), "e".into(), "r".into(), "t".into(), "y".into(), "u".into(), "i".into(), "o".into(), "p".into(), "^".into(), "$".into()],
                    vec!["q".into(), "s".into(), "d".into(), "f".into(), "g".into(), "h".into(), "j".into(), "k".into(), "l".into(), "m".into(), "ù".into()],
                    vec!["w".into(), "x".into(), "c".into(), "v".into(), "b".into(), "n".into(), ",".into(), ";".into(), ":".into(), "!".into()],
                ],
            },
            "qwertz" => Layout {
                rows: [
                    vec!["q".into(), "w".into(), "e".into(), "r".into(), "t".into(), "z".into(), "u".into(), "i".into(), "o".into(), "p".into(), "ü".into(), "+".into()],
                    vec!["a".into(), "s".into(), "d".into(), "f".into(), "g".into(), "h".into(), "j".into(), "k".into(), "l".into(), "ö".into(), "ä".into()],
                    vec!["y".into(), "x".into(), "c".into(), "v".into(), "b".into(), "n".into(), "m".into(), ",".into(), ".".into(), "-".into()],
                ],
            },
            _ => Layout {
                rows: [
                    vec!["q".into(), "w".into(), "e".into(), "r".into(), "t".into(), "y".into(), "u".into(), "i".into(), "o".into(), "p".into(), "[".into(), "]".into()],
                    vec!["a".into(), "s".into(), "d".into(), "f".into(), "g".into(), "h".into(), "j".into(), "k".into(), "l".into(), ";".into(), "'".into()],
                    vec!["z".into(), "x".into(), "c".into(), "v".into(), "b".into(), "n".into(), "m".into(), ",".into(), ".".into(), "/".into()],
                ],
            },
        }
    }

    fn get_key_pos(&self, c: char) -> Option<(usize, usize)> {
        for (r, row) in self.rows.iter().enumerate() {
            for (col, key) in row.iter().enumerate() {
                if key.chars().next() == Some(c) {
                    return Some((r, col));
