fn main() -> io::Result<()> {
    let args = Args::parse();
    let ngrams: Vec<String> = if std::path::Path::new(&args.n).exists() {
        let content = std::fs::read_to_string(&args.n)?;
        content.split(',').map(|s| s.trim().to_string()).collect()
    } else {
        let list = match args.n.as_str() {
            "3" => TRIGRAMS,
            "4" => TETRAGRAMS,
            "w" => WORDS,
            _ => BIGRAMS,
        };
        list.iter().take(args.top).map(|s| s.to_string()).collect()
    };

    let emu_in = if args.emu_in.is_empty() { None } else { Some(Layout::new(&args.emu_in)) };
    let emu_out = if args.emu_out.is_empty() { None } else { Some(Layout::new(&args.emu_out)) };

    terminal::enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, terminal::EnterAlternateScreen, cursor::Hide)?;

    let mut lesson_num = 1;
    let mut success_count = 0;
    let mut failure_count = 0;
    let mut wpms = Vec::new();
    let mut accs = Vec::new();

    loop {
        let res = run_lesson(
            &mut stdout,
            &args,
            &ngrams,
            lesson_num,
            success_count,
            failure_count,
            &wpms,
            &accs,
