    }

    execute!(stdout, cursor::Show, terminal::LeaveAlternateScreen)?;
    terminal::disable_raw_mode()?;
    Ok(())
}

enum LessonResult {
    Quit,
    Finished { wpm: f64, acc: f64, success: bool },
}

fn run_lesson(
    stdout: &mut Stdout,
    args: &Args,
    ngrams: &[String],
    lesson_num: usize,
    success_count: usize,
    failure_count: usize,
    wpms: &[f64],
    accs: &[f64],
    emu_in: &Option<Layout>,
    emu_out: &Option<Layout>,
) -> io::Result<LessonResult> {
    let mut rng = rand::thread_rng();
    let selected: Vec<String> = ngrams.choose_multiple(&mut rng, args.combi).cloned().collect();
    let mut lesson_text = String::new();
    for _ in 0..args.rep {
        for word in &selected {
            if !lesson_text.is_empty() { lesson_text.push(' '); }
            lesson_text.push_str(word);
        }
    }
    lesson_text.push(' ');

    let mut inputs = Vec::new();
    let mut start_time: Option<Instant> = None;

    loop {
        render(stdout, args, &lesson_text, &inputs, lesson_num, success_count, failure_count, wpms, accs, emu_out)?;

        if inputs.len() == lesson_text.len() {
            let elapsed = start_time.map(|t| t.elapsed()).unwrap_or(Duration::from_secs(0));
            let wpm = if elapsed.as_secs_f64() > 0.0 { (lesson_text.len() as f64 / 5.0) / (elapsed.as_secs_f64() / 60.0) } else { 0.0 };
            let mut correct = 0;
            for (i, &c) in inputs.iter().enumerate() {
                if c == lesson_text.chars().nth(i).unwrap() { correct += 1; }
            }
            let acc = (correct as f64 / inputs.len() as f64) * 100.0;
            return Ok(LessonResult::Finished { wpm, acc, success: wpm >= args.wpm as f64 && acc >= args.acc as f64 });
        }

        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
            if code == KeyCode::Esc { return Ok(LessonResult::Quit); }
            if let KeyCode::Char(input_char) = code {
                if start_time.is_none() { start_time = Some(Instant::now()); }
                let effective_char = if let (Some(in_l), Some(out_l)) = (emu_in, emu_out) {
                    if let Some(pos) = in_l.get_key_pos(input_char) {
                        out_l.rows[pos.0][pos.1].chars().next().unwrap()
                    } else { input_char }
                } else { input_char };
                inputs.push(effective_char);
            }
        }
    }
}

fn render(
    stdout: &mut Stdout,
    args: &Args,
    target: &str,
    inputs: &[char],
    lesson_num: usize,
    success_count: usize,
    failure_count: usize,
    wpms: &[f64],
    accs: &[f64],
    emu_out: &Option<Layout>,
) -> io::Result<()> {
    execute!(stdout, cursor::MoveTo(0, 0))?;
    let width = 79;

    // Top border
    print_border(stdout, "╭", "─", "╮", width, Some(" Quit <esc> "), true)?;

    // Title
    print_line(stdout, &format!("{:^width$}", "ngrrram!   by winterveil", width = width - 2))?;

    // Divider
    print_divider(stdout, "├", "─", "┤", width, None)?;

    // Lesson info
    let lesson_info = format!("    Lesson #{} ", lesson_num);
    let counts = format!("✔: {}, ✘: {}    ", success_count, failure_count);
    let mid_width = width - 2 - lesson_info.len() - counts.len();
    print!("│");
    print!("{}", lesson_info);
    print!("{:width$}", "", width = mid_width);
    execute!(stdout, style::SetForegroundColor(Color::Green))?;
    print!("✔: {}", success_count);
    execute!(stdout, style::SetForegroundColor(Color::Red))?;
    print!(", ✘: {}", failure_count);
    execute!(stdout, style::ResetColor)?;
    println!("    │");

    // Divider
    print_divider(stdout, "├", "─", "┤", width, None)?;

    // Text to type
    print_line(stdout, "")?;
    let target_display = target.trim_end();
    let padding = (width - 2 - target_display.len()) / 2;
    print!("│");
    print!("{:width$}", "", width = padding);
    for (i, c) in target_display.chars().enumerate() {
        if i < inputs.len() {
            if inputs[i] == c {
                execute!(stdout, style::SetForegroundColor(Color::Green), style::SetAttribute(Attribute::Bold))?;
            } else {
                execute!(stdout, style::SetForegroundColor(Color::Red), style::SetAttribute(Attribute::Bold))?;
            }
        }
        print!("{}", c);
        execute!(stdout, style::ResetColor)?;
    }
    let remaining_padding = width - 2 - padding - target_display.len();
    println!("{:width$}│", "", width = remaining_padding);

    // User input row
    print!("│");
    print!("{:width$}", "", width = padding);
    for i in 0..target_display.len() {
        if i < inputs.len() && inputs[i] != target_display.chars().nth(i).unwrap() {
            execute!(stdout, style::SetForegroundColor(Color::Grey), style::SetAttribute(Attribute::Italic))?;
            print!("{}", inputs[i]);
            execute!(stdout, style::ResetColor)?;
        } else {
            print!(" ");
        }
    }
    println!("{:width$}│", "", width = remaining_padding);

    // Keyboard
    if !args.nokb {
        let layout = emu_out.as_ref().unwrap_or(&Layout::new("qwerty"));
        if args.show_ortho {
            render_ortho(stdout, layout, args.cat)?;
        } else {
            render_staggered(stdout, layout, args.cat)?;
        }
    } else {
        for _ in 0..7 { print_line(stdout, "")?; }
    }

    // Stats
    let avg_wpm = if wpms.is_empty() { 0 } else { (wpms.iter().sum::<f64>() / wpms.len() as f64) as u32 };
    let last_wpm = wpms.last().map(|&w| w as u32).unwrap_or(0);
    let avg_acc = if accs.is_empty() { 0 } else { (accs.iter().sum::<f64>() / accs.len() as f64) as u32 };
    let last_acc = accs.last().map(|&a| a as u32).unwrap_or(0);

    let divider = if args.cat { "│────────────────────────────────────────────────────────────/▔▔▔▔▔▔▔▔||▔▔\\───│" } else { "│─────────────────────────────────────────────────────────────────────────────│" };
    println!("{}", divider);

    let stat1 = format!("  need >=  {}WPM,   avg. {:>3}WPM,   last {:>3}WPM", args.wpm, avg_wpm, last_wpm);
    if args.cat {
        println!("│{:width$}                       \\\\      │", stat1, width = width - 33);
    } else {
        print_line(stdout, &stat1)?;
    }

    let stat2 = format!("  need >=  {}% Acc, avg. {:>3}% Acc, last {:>3}% Acc", args.acc, avg_acc, last_acc);
    if args.cat {
        println!("│{:width$}                      V      │", stat2, width = width - 32);
    } else {
        print_line(stdout, &stat2)?;
    }

    print_border(stdout, "╰", "─", "╯", width, None, false)?;

    stdout.flush()?;
    Ok(())
}

fn print_border(stdout: &mut Stdout, left: &str, mid: &str, right: &str, width: usize, label: Option<&str>, is_top: bool) -> io::Result<()> {
    print!("{}", left);
    if let Some(l) = label {
        let dashes = width - 2 - l.len();
        print!("{}", mid.repeat(dashes));
        if is_top {
            execute!(stdout, style::SetForegroundColor(Color::Blue), style::SetAttribute(Attribute::Bold))?;
            print!("{}", l);
            execute!(stdout, style::ResetColor)?;
        } else {
            print!("{}", l);
        }
    } else {
        print!("{}", mid.repeat(width - 2));
    }
    println!("{}", right);
    Ok(())
}

fn print_line(stdout: &mut Stdout, text: &str) -> io::Result<()> {
    println!("│{:width$}│", text, width = 77);
    Ok(())
}

fn print_divider(stdout: &mut Stdout, left: &str, mid: &str, right: &str, width: usize, label: Option<&str>) -> io::Result<()> {
    print!("{}", left);
    print!("{}", mid.repeat(width - 2));
    println!("{}", right);
    Ok(())
}

fn render_staggered(stdout: &mut Stdout, layout: &Layout, cat: bool) -> io::Result<()> {
    let padding = "             ";
    let cat_art = if cat { vec!["", "", " /\\_/\\", ">(•༝• )<", " |    \\", " || |  )", " ll-l-//"] } else { vec![""; 7] };

    // Row 1
    print!("│{}", padding);
