    println!("{:width$}{}│", "", cat_art[0], width = 77 - padding.len() - 49 - cat_art[0].len());

    print!("│{}", padding);
    print!("│");
    for (i, key) in layout.rows[0].iter().enumerate() {
        print!(" {} │", key);
    }
    println!("{:width$}{}│", "", cat_art[1], width = 77 - padding.len() - 49 - cat_art[1].len());

    print!("│{}", padding);
    print!("└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
    println!("{:width$}{}│", "", cat_art[2], width = 77 - padding.len() - 49 - cat_art[2].len());

    // Row 2
    let p2 = "              ";
    print!("│{}", p2);
    print!("│");
    for key in &layout.rows[1] { print!(" {} │", key); }
    println!("{:width$}{}│", "", cat_art[3], width = 77 - p2.len() - 45 - cat_art[3].len());

    print!("│{}", p2);
    print!("└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
    println!("{:width$}{}│", "", cat_art[4], width = 77 - p2.len() - 45 - cat_art[4].len());

    // Row 3
    let p3 = "               ";
    print!("│{}", p3);
    print!("│");
    for key in &layout.rows[2] { print!(" {} │", key); }
    println!("{:width$}{}│", "", cat_art[5], width = 77 - p3.len() - 41 - cat_art[5].len());

    print!("│{}", p3);
    print!("└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘");
    println!("{:width$}{}│", "", cat_art[6], width = 77 - p3.len() - 41 - cat_art[6].len());

    Ok(())
}

fn render_ortho(stdout: &mut Stdout, layout: &Layout, cat: bool) -> io::Result<()> {
    let padding = "             ";
    let cat_art = if cat { vec![" /\\_/\\", ">(•༝• )<", " |    \\", " || |  )", " ll-l-//"] } else { vec![""; 5] };

    print!("│{}", padding);
    println!("┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐{:width$}│", "", width = 77-padding.len()-49);

    for r in 0..3 {
        print!("│{}", padding);
        print!("│");
        for c in 0..12 {
            let key = layout.rows[r].get(c).map(|s| s.as_str()).unwrap_or("△");
            print!(" {} │", key);
        }
        let art = if r*2 < cat_art.len() { cat_art[r*2] } else { "" };
        println!("{:width$}{}│", "", art, width = 77-padding.len()-49-art.len());

        print!("│{}", padding);
        if r < 2 {
            print!("├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤");
            let art = if r*2+1 < cat_art.len() { cat_art[r*2+1] } else { "" };
            println!("{:width$}{}│", "", art, width = 77-padding.len()-49-art.len());
        } else {
            println!("└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘{:width$}│", "", width = 77-padding.len()-49);
        }
    }
    Ok(())
}
EOF
"}

