                    vec![";".into(), "q".into(), "j".into(), "k".into(), "x".into(), "b".into(), "m".into(), "w".into(), "v".into(), "z".into()],
                ],
            },
            "colemak" => Layout {
                rows: [
                    vec!["q".into(), "w".into(), "f".into(), "p".into(), "g".into(), "j".into(), "l".into(), "u".into(), "y".into(), ";".into(), "[".into(), "]".into()],
                    vec!["a".into(), "r".into(), "s".into(), "t".into(), "d".into(), "h".into(), "n".into(), "e".into(), "i".into(), "o".into(), "'".into()],
                    vec!["z".into(), "x".into(), "c".into(), "v".into(), "b".into(), "k".into(), "m".into(), ",".into(), ".".into(), "/".into()],
                ],
            },
            "colemakdh" => Layout {
                rows: [
                    vec!["q".into(), "w".into(), "f".into(), "p".into(), "b".into(), "j".into(), "l".into(), "u".into(), "y".into(), ";".into(), "[".into(), "]".into()],
                    vec!["a".into(), "r".into(), "s".into(), "t".into(), "g".into(), "m".into(), "n".into(), "e".into(), "i".into(), "o".into(), "'".into()],
                    vec!["z".into(), "x".into(), "c".into(), "d".into(), "v".into(), "k".into(), "h".into(), ",".into(), ".".into(), "/".into()],
                ],
            },
            "azerty" => Layout {
                rows: [
                    vec!["a".into(), "z".into(), "e".into(), "r".into(), "t".into(), "y".into(), "u".into(), "i".into(), "o".into(), "p".into(), "^".into(), "$".into()],
                    vec!["q".into(), "s".into(), "d".into(), "f".into(), "g".into(), "h".into(), "j".into(), "k".into(), "l".into(), "m".into(), "ù".into()],
                    vec!["w".into(), "x".into(), "c".into(), "v".into(), "b".into(), "n".into(), ",".into(), ";".into(), ":".into(), "!".into()],
                ],
            },
            "qwertz" => Layout {
                rows: [
                    vec!["q".into(), "w".into(), "e".into(), "r".into(), "t".into(), "z".into(), "u".into(), "i".into(), "o".into(), "p".into(), "ü".into(), "+".into()],
                    vec!["a".into(), "s".into(), "d".into(), "f".into(), "g".into(), "h".into(), "j".into(), "k".into(), "l".into(), "ö".into(), "ä".into()],
                    vec!["y".into(), "x".into(), "c".into(), "v".into(), "b".into(), "n".into(), "m".into(), ",".into(), ".".into(), "-".into()],
                ],
            },
            _ => Layout {
                rows: [
                    vec!["q".into(), "w".into(), "e".into(), "r".into(), "t".into(), "y".into(), "u".into(), "i".into(), "o".into(), "p".into(), "[".into(), "]".into()],
                    vec!["a".into(), "s".into(), "d".into(), "f".into(), "g".into(), "h".into(), "j".into(), "k".into(), "l".into(), ";".into(), "'".into()],
                    vec!["z".into(), "x".into(), "c".into(), "v".into(), "b".into(), "n".into(), "m".into(), ",".into(), ".".into(), "/".into()],
                ],
            },
        }
    }

    fn get_key_pos(&self, c: char) -> Option<(usize, usize)> {
        for (r, row) in self.rows.iter().enumerate() {
            for (col, key) in row.iter().enumerate() {
                if key.chars().next() == Some(c) {
                    return Some((r, col));
                }
            }
        }
        None
    }
}

const BIGRAMS: &[&str] = &["th", "he", "in", "er", "an", "re", "on", "at", "en", "nd", "ti", "es", "or", "te", "of", "ed", "is", "it", "al", "ar", "st", "to", "nt", "ng", "se", "ha", "as", "ou", "io", "le", "hi", "ve", "me", "de", "rt", "ne", "li", "be", "ma", "ot", "ta", "ll", "ic", "ch", "ss", "ea", "la", "pr", "ri", "om"];
const TRIGRAMS: &[&str] = &["the", "and", "ing", "her", "hat", "his", "tha", "ere", "for", "ent", "ion", "ter", "was", "you", "ith", "ver", "all", "wit", "thi", "tio"];
const TETRAGRAMS: &[&str] = &["tion", "that", "ther", "with", "ment", "ions", "this", "here", "from", "ould", "ting", "hich", "whic", "ctio", "ence", "have", "othe", "ight", "sion", "ever"];
const WORDS: &[&str] = &["the", "of", "and", "a", "to", "in", "is", "you", "that", "it", "he", "was", "for", "on", "are", "as", "with", "his", "they", "i", "at", "be", "this", "have", "from", "or", "one", "had", "by", "word", "but", "not", "what", "all", "were", "we", "when", "your", "can", "said", "there", "use", "an", "each", "which", "she", "do", "how", "their", "if", "will", "up", "other", "about", "out", "many", "then", "them", "these", "so", "some", "her", "would", "make", "like", "him", "into", "time", "has", "look", "two", "more", "write", "go", "see", "number", "no", "way", "could", "people", "my", "than", "first", "water", "been", "called", "who", "oil", "its", "now", "find", "long", "down", "day", "did", "get", "come", "made", "may", "part"];

fn main() -> io::Result<()> {
    let args = Args::parse();
    let ngrams: Vec<String> = if std::path::Path::new(&args.n).exists() {
        let content = std::fs::read_to_string(&args.n)?;
        content.split(',').map(|s| s.trim().to_string()).collect()
    } else {
        let list = match args.n.as_str() {
            "3" => TRIGRAMS,
            "4" => TETRAGRAMS,
            "w" => WORDS,
            _ => BIGRAMS,
        };
        list.iter().take(args.top).map(|s| s.to_string()).collect()
    };

    let emu_in = if args.emu_in.is_empty() { None } else { Some(Layout::new(&args.emu_in)) };
    let emu_out = if args.emu_out.is_empty() { None } else { Some(Layout::new(&args.emu_out)) };

    terminal::enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, terminal::EnterAlternateScreen, cursor::Hide)?;

    let mut lesson_num = 1;
    let mut success_count = 0;
    let mut failure_count = 0;
    let mut wpms = Vec::new();
    let mut accs = Vec::new();

    loop {
        let res = run_lesson(
            &mut stdout,
            &args,
            &ngrams,
            lesson_num,
            success_count,
            failure_count,
            &wpms,
            &accs,
            &emu_in,
            &emu_out,
        )?;
        match res {
            LessonResult::Quit => break,
            LessonResult::Finished { wpm, acc, success } => {
                wpms.push(wpm);
                accs.push(acc);
                if success { success_count += 1; } else { failure_count += 1; }
                lesson_num += 1;
            }
        }
    }

    execute!(stdout, cursor::Show, terminal::LeaveAlternateScreen)?;
    terminal::disable_raw_mode()?;
    Ok(())
}

enum LessonResult {
    Quit,
    Finished { wpm: f64, acc: f64, success: bool },
}

fn run_lesson(
    stdout: &mut Stdout,
    args: &Args,
    ngrams: &[String],
    lesson_num: usize,
    success_count: usize,
    failure_count: usize,
    wpms: &[f64],
    accs: &[f64],
    emu_in: &Option<Layout>,
    emu_out: &Option<Layout>,
) -> io::Result<LessonResult> {
    let mut rng = rand::thread_rng();
    let selected: Vec<String> = ngrams.choose_multiple(&mut rng, args.combi).cloned().collect();
    let mut lesson_text = String::new();
    for _ in 0..args.rep {
        for word in &selected {
            if !lesson_text.is_empty() { lesson_text.push(' '); }
            lesson_text.push_str(word);
        }
    }
    lesson_text.push(' ');

    let mut inputs = Vec::new();
    let mut start_time: Option<Instant> = None;

    loop {
        render(stdout, args, &lesson_text, &inputs, lesson_num, success_count, failure_count, wpms, accs, emu_out)?;

        if inputs.len() == lesson_text.len() {
            let elapsed = start_time.map(|t| t.elapsed()).unwrap_or(Duration::from_secs(0));
            let wpm = if elapsed.as_secs_f64() > 0.0 { (lesson_text.len() as f64 / 5.0) / (elapsed.as_secs_f64() / 60.0) } else { 0.0 };
            let mut correct = 0;
            for (i, &c) in inputs.iter().enumerate() {
                if c == lesson_text.chars().nth(i).unwrap() { correct += 1; }
            }
            let acc = (correct as f64 / inputs.len() as f64) * 100.0;
            return Ok(LessonResult::Finished { wpm, acc, success: wpm >= args.wpm as f64 && acc >= args.acc as f64 });
        }

        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
            if code == KeyCode::Esc { return Ok(LessonResult::Quit); }
            if let KeyCode::Char(input_char) = code {
                if start_time.is_none() { start_time = Some(Instant::now()); }
                let effective_char = if let (Some(in_l), Some(out_l)) = (emu_in, emu_out) {
                    if let Some(pos) = in_l.get_key_pos(input_char) {
                        out_l.rows[pos.0][pos.1].chars().next().unwrap()
                    } else { input_char }
                } else { input_char };
                inputs.push(effective_char);
            }
        }
    }
}

fn render(
    stdout: &mut Stdout,
    args: &Args,
    target: &str,
    inputs: &[char],
    lesson_num: usize,
    success_count: usize,
    failure_count: usize,
    wpms: &[f64],
    accs: &[f64],
    emu_out: &Option<Layout>,
) -> io::Result<()> {
    execute!(stdout, cursor::MoveTo(0, 0))?;
    let width = 79;

    // Top border
    print_border(stdout, "╭", "─", "╮", width, Some(" Quit <esc> "), true)?;

    // Title
    print_line(stdout, &format!("{:^width$}", "ngrrram!   by winterveil", width = width - 2))?;

    // Divider
    print_divider(stdout, "├", "─", "┤", width, None)?;

    // Lesson info
    let lesson_info = format!("    Lesson #{} ", lesson_num);
    let counts = format!("✔: {}, ✘: {}    ", success_count, failure_count);
    let mid_width = width - 2 - lesson_info.len() - counts.len();
    print!("│");
    print!("{}", lesson_info);
    print!("{:width$}", "", width = mid_width);
    execute!(stdout, style::SetForegroundColor(Color::Green))?;
    print!("✔: {}", success_count);
    execute!(stdout, style::SetForegroundColor(Color::Red))?;
    print!(", ✘: {}", failure_count);
    execute!(stdout, style::ResetColor)?;
    println!("    │");

    // Divider
    print_divider(stdout, "├", "─", "┤", width, None)?;

    // Text to type
    print_line(stdout, "")?;
    let target_display = target.trim_end();
    let padding = (width - 2 - target_display.len()) / 2;
    print!("│");
    print!("{:width$}", "", width = padding);
    for (i, c) in target_display.chars().enumerate() {
        if i < inputs.len() {
            if inputs[i] == c {
                execute!(stdout, style::SetForegroundColor(Color::Green), style::SetAttribute(Attribute::Bold))?;
            } else {
                execute!(stdout, style::SetForegroundColor(Color::Red), style::SetAttribute(Attribute::Bold))?;
            }
        }
        print!("{}", c);
        execute!(stdout, style::ResetColor)?;
    }
    let remaining_padding = width - 2 - padding - target_display.len();
    println!("{:width$}│", "", width = remaining_padding);

    // User input row
    print!("│");
    print!("{:width$}", "", width = padding);
    for i in 0..target_display.len() {
        if i < inputs.len() && inputs[i] != target_display.chars().nth(i).unwrap() {
            execute!(stdout, style::SetForegroundColor(Color::Grey), style::SetAttribute(Attribute::Italic))?;
            print!("{}", inputs[i]);
            execute!(stdout, style::ResetColor)?;
        } else {
            print!(" ");
        }
    }
    println!("{:width$}│", "", width = remaining_padding);

    // Keyboard
    if !args.nokb {
        let layout = emu_out.as_ref().unwrap_or(&Layout::new("qwerty"));
        if args.show_ortho {
            render_ortho(stdout, layout, args.cat)?;
        } else {
            render_staggered(stdout, layout, args.cat)?;
        }
    } else {
        for _ in 0..7 { print_line(stdout, "")?; }
    }

    // Stats
    let avg_wpm = if wpms.is_empty() { 0 } else { (wpms.iter().sum::<f64>() / wpms.len() as f64) as u32 };
    let last_wpm = wpms.last().map(|&w| w as u32).unwrap_or(0);
    let avg_acc = if accs.is_empty() { 0 } else { (accs.iter().sum::<f64>() / accs.len() as f64) as u32 };
    let last_acc = accs.last().map(|&a| a as u32).unwrap_or(0);

    let divider = if args.cat { "│────────────────────────────────────────────────────────────/▔▔▔▔▔▔▔▔||▔▔\\───│" } else { "│─────────────────────────────────────────────────────────────────────────────│" };
    println!("{}", divider);

    let stat1 = format!("  need >=  {}WPM,   avg. {:>3}WPM,   last {:>3}WPM", args.wpm, avg_wpm, last_wpm);
    if args.cat {
        println!("│{:width$}                       \\\\      │", stat1, width = width - 33);
    } else {
        print_line(stdout, &stat1)?;
    }

    let stat2 = format!("  need >=  {}% Acc, avg. {:>3}% Acc, last {:>3}% Acc", args.acc, avg_acc, last_acc);
    if args.cat {
        println!("│{:width$}                      V      │", stat2, width = width - 32);
    } else {
        print_line(stdout, &stat2)?;
    }

    print_border(stdout, "╰", "─", "╯", width, None, false)?;

    stdout.flush()?;
    Ok(())
}

fn print_border(stdout: &mut Stdout, left: &str, mid: &str, right: &str, width: usize, label: Option<&str>, is_top: bool) -> io::Result<()> {
    print!("{}", left);
    if let Some(l) = label {
        let dashes = width - 2 - l.len();
        print!("{}", mid.repeat(dashes));
        if is_top {
            execute!(stdout, style::SetForegroundColor(Color::Blue), style::SetAttribute(Attribute::Bold))?;
            print!("{}", l);
            execute!(stdout, style::ResetColor)?;
        } else {
            print!("{}", l);
        }
    } else {
        print!("{}", mid.repeat(width - 2));
    }
    println!("{}", right);
    Ok(())
}

fn print_line(stdout: &mut Stdout, text: &str) -> io::Result<()> {
    println!("│{:width$}│", text, width = 77);
    Ok(())
}

fn print_divider(stdout: &mut Stdout, left: &str, mid: &str, right: &str, width: usize, label: Option<&str>) -> io::Result<()> {
    print!("{}", left);
    print!("{}", mid.repeat(width - 2));
    println!("{}", right);
    Ok(())
}

fn render_staggered(stdout: &mut Stdout, layout: &Layout, cat: bool) -> io::Result<()> {
    let padding = "             ";
    let cat_art = if cat { vec!["", "", " /\\_/\\", ">(•༝• )<", " |    \\", " || |  )", " ll-l-//"] } else { vec![""; 7] };

    // Row 1
    print!("│{}", padding);
    print!("┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐");
    println!("{:width$}{}│", "", cat_art[0], width = 77 - padding.len() - 49 - cat_art[0].len());

    print!("│{}", padding);
    print!("│");
    for (i, key) in layout.rows[0].iter().enumerate() {
        print!(" {} │", key);
    }
    println!("{:width$}{}│", "", cat_art[1], width = 77 - padding.len() - 49 - cat_art[1].len());

    print!("│{}", padding);
    print!("└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
    println!("{:width$}{}│", "", cat_art[2], width = 77 - padding.len() - 49 - cat_art[2].len());

    // Row 2
    let p2 = "              ";
    print!("│{}", p2);
    print!("│");
    for key in &layout.rows[1] { print!(" {} │", key); }
    println!("{:width$}{}│", "", cat_art[3], width = 77 - p2.len() - 45 - cat_art[3].len());

    print!("│{}", p2);
    print!("└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
    println!("{:width$}{}│", "", cat_art[4], width = 77 - p2.len() - 45 - cat_art[4].len());

    // Row 3
    let p3 = "               ";
    print!("│{}", p3);
    print!("│");
    for key in &layout.rows[2] { print!(" {} │", key); }
    println!("{:width$}{}│", "", cat_art[5], width = 77 - p3.len() - 41 - cat_art[5].len());

    print!("│{}", p3);
    print!("└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘");
    println!("{:width$}{}│", "", cat_art[6], width = 77 - p3.len() - 41 - cat_art[6].len());

    Ok(())
}

fn render_ortho(stdout: &mut Stdout, layout: &Layout, cat: bool) -> io::Result<()> {
    let padding = "             ";
    let cat_art = if cat { vec![" /\\_/\\", ">(•༝• )<", " |    \\", " || |  )", " ll-l-//"] } else { vec![""; 5] };

    print!("│{}", padding);
    println!("┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐{:width$}│", "", width = 77-padding.len()-49);

    for r in 0..3 {
        print!("│{}", padding);
        print!("│");
        for c in 0..12 {
            let key = layout.rows[r].get(c).map(|s| s.as_str()).unwrap_or("△");
            print!(" {} │", key);
        }
        let art = if r*2 < cat_art.len() { cat_art[r*2] } else { "" };
        println!("{:width$}{}│", "", art, width = 77-padding.len()-49-art.len());

        print!("│{}", padding);
        if r < 2 {
            print!("├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤");
            let art = if r*2+1 < cat_art.len() { cat_art[r*2+1] } else { "" };
            println!("{:width$}{}│", "", art, width = 77-padding.len()-49-art.len());
        } else {
            println!("└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘{:width$}│", "", width = 77-padding.len()-49);
        }
    }
    Ok(())
}
